import {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ReactElement,
  type ReactNode,
} from 'react';
import { StyleSheet, Text, View, type TextProps, type ViewProps } from 'react-native';
import { useGlassTheme } from './glass-provider';
import {
  AnchoredContent,
  OverlayItem,
  OverlayLabel,
  OverlaySeparator,
  OverlayTrigger,
  type OverlayItemProps,
  type OverlayPlacementProps,
  type OverlayTriggerChildProps,
} from './lib/anchored-overlay';
import { GlassIcon } from './lib/icons';
import { useControllableState } from './lib/use-controllable-state';

type MenuContextValue = {
  anchor: View | null;
  open: boolean;
  setAnchor: (node: View | null) => void;
  setOpen: (open: boolean) => void;
};

const MenuContext = createContext<MenuContextValue | null>(null);

function useMenuContext(component: string) {
  const context = useContext(MenuContext);

  if (!context) throw new Error(`${component} must be used within GlassMenu`);

  return context;
}

type RadioGroupContextValue = {
  onValueChange?: (value: string) => void;
  value?: string;
};

const RadioGroupContext = createContext<RadioGroupContextValue | null>(null);

function useRadioGroupContext() {
  const context = useContext(RadioGroupContext);

  if (!context) throw new Error('GlassMenuRadioItem must be used within GlassMenuRadioGroup');

  return context;
}

// The web's lg-menu-content: 14rem wide at least, with 1.125rem corners.
const MENU_MIN_WIDTH = 224;

const MENU_RADIUS = 18;

export type GlassMenuProps = {
  children?: ReactNode;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  open?: boolean;
};

/** Holds a menu's open state for its trigger and content. */
export function GlassMenu({ children, defaultOpen = false, onOpenChange, open }: GlassMenuProps) {
  const [isOpen, setOpen] = useControllableState(open, defaultOpen, onOpenChange);
  const [anchor, setAnchor] = useState<View | null>(null);

  const value = useMemo(
    () => ({ anchor, open: isOpen, setAnchor, setOpen }),
    [anchor, isOpen, setOpen],
  );

  return <MenuContext.Provider value={value}>{children}</MenuContext.Provider>;
}

export type GlassMenuTriggerProps = {
  /** One pressable element, such as a GlassButton, that passes its ref to a view. */
  children: ReactElement<OverlayTriggerChildProps>;
};

/** Opens the menu from its one child, such as a GlassButton, and marks that child expanded. */
export function GlassMenuTrigger({ children }: GlassMenuTriggerProps) {
  const menu = useMenuContext('GlassMenuTrigger');

  return (
    <OverlayTrigger onAnchor={menu.setAnchor} onOpenChange={menu.setOpen} open={menu.open}>
      {children}
    </OverlayTrigger>
  );
}

export type GlassMenuContentProps = Omit<ViewProps, 'children'> &
  OverlayPlacementProps & {
    children?: ReactNode;
  };

/** The open menu: a glass slab that grows out of its trigger and scrolls when it runs out of room. */
export const GlassMenuContent = forwardRef<View, GlassMenuContentProps>(
  ({ align = 'center', children, ...rest }, ref) => {
    const { anchor, open, setOpen } = useMenuContext('GlassMenuContent');
    const close = useCallback(() => setOpen(false), [setOpen]);

    return (
      <AnchoredContent
        ref={ref}
        accessibilityRole="menu"
        align={align}
        anchor={anchor}
        minWidth={MENU_MIN_WIDTH}
        onClose={close}
        open={open}
        padding={6}
        radius={MENU_RADIUS}
        {...rest}
      >
        {children}
      </AnchoredContent>
    );
  },
);

GlassMenuContent.displayName = 'GlassMenuContent';

export type GlassMenuSelectEvent = {
  defaultPrevented: boolean;
  /** Keeps the menu open after this selection. */
  preventDefault: () => void;
};

function createSelectEvent(): GlassMenuSelectEvent {
  const event = {
    defaultPrevented: false,
    preventDefault: () => {
      event.defaultPrevented = true;
    },
  };

  return event;
}

export type GlassMenuItemProps = Omit<OverlayItemProps, 'indicator' | 'onPress' | 'textStyle'> & {
  /** Runs when the row is chosen. The menu then closes unless the handler prevents it. */
  onSelect?: (event: GlassMenuSelectEvent) => void;
};

type MenuRowProps = GlassMenuItemProps & {
  indicator?: ReactNode;
};

const MenuRow = forwardRef<View, MenuRowProps>(({ onSelect, ...rest }, ref) => {
  const { setOpen } = useMenuContext('GlassMenuItem');

  const handlePress = useCallback(() => {
    const event = createSelectEvent();

    onSelect?.(event);

    if (!event.defaultPrevented) setOpen(false);
  }, [onSelect, setOpen]);

  return <OverlayItem ref={ref} onPress={handlePress} {...rest} />;
});

MenuRow.displayName = 'MenuRow';

/** A menu row that runs `onSelect` and closes the menu. */
export const GlassMenuItem = forwardRef<View, GlassMenuItemProps>((props, ref) => (
  <MenuRow ref={ref} {...props} />
));

GlassMenuItem.displayName = 'GlassMenuItem';

export type GlassMenuCheckboxItemProps = Omit<GlassMenuItemProps, 'inset' | 'tone'> & {
  checked?: boolean | 'indeterminate';
  onCheckedChange?: (checked: boolean) => void;
};

/** A menu row that toggles a setting and shows a check while it is on. */
export const GlassMenuCheckboxItem = forwardRef<View, GlassMenuCheckboxItemProps>(
  ({ checked = false, onCheckedChange, onSelect, ...rest }, ref) => {
    const { colors } = useGlassTheme();
    const mixed = checked === 'indeterminate';

    const handleSelect = useCallback(
      (event: GlassMenuSelectEvent) => {
        onSelect?.(event);
        onCheckedChange?.(mixed ? true : !checked);
      },
      [checked, mixed, onCheckedChange, onSelect],
    );

    return (
      <MenuRow
        ref={ref}
        accessibilityState={{ checked: mixed ? 'mixed' : checked }}
        indicator={
          checked ? (
            <GlassIcon color={colors.foreground} name={mixed ? 'dash' : 'check'} size={16} />
          ) : null
        }
        inset
        onSelect={handleSelect}
        {...rest}
      />
    );
  },
);

GlassMenuCheckboxItem.displayName = 'GlassMenuCheckboxItem';

export type GlassMenuRadioGroupProps = ViewProps & {
  onValueChange?: (value: string) => void;
  value?: string;
};

/** Groups radio rows; the row whose value matches `value` shows a dot. */
export const GlassMenuRadioGroup = forwardRef<View, GlassMenuRadioGroupProps>(
  ({ onValueChange, value, ...rest }, ref) => {
    const group = useMemo(() => ({ onValueChange, value }), [onValueChange, value]);

    return (
      <RadioGroupContext.Provider value={group}>
        <View ref={ref} accessibilityRole="radiogroup" {...rest} />
      </RadioGroupContext.Provider>
    );
  },
);

GlassMenuRadioGroup.displayName = 'GlassMenuRadioGroup';

export type GlassMenuRadioItemProps = Omit<GlassMenuItemProps, 'inset' | 'tone'> & {
  value: string;
};

/** A menu row that chooses one value from its radio group. */
export const GlassMenuRadioItem = forwardRef<View, GlassMenuRadioItemProps>(
  ({ onSelect, value, ...rest }, ref) => {
    const { colors } = useGlassTheme();
    const group = useRadioGroupContext();
    const { onValueChange } = group;
    const checked = group.value === value;

    const handleSelect = useCallback(
      (event: GlassMenuSelectEvent) => {
        onSelect?.(event);
        onValueChange?.(value);
      },
      [onSelect, onValueChange, value],
    );

    return (
      <MenuRow
        ref={ref}
        accessibilityState={{ checked }}
        indicator={
          checked ? <View style={[styles.dot, { backgroundColor: colors.foreground }]} /> : null
        }
        inset
        onSelect={handleSelect}
        {...rest}
      />
    );
  },
);

GlassMenuRadioItem.displayName = 'GlassMenuRadioItem';

/** A small muted heading over a group of menu rows. */
export const GlassMenuLabel = forwardRef<Text, TextProps>((props, ref) => (
  <OverlayLabel ref={ref} {...props} />
));

GlassMenuLabel.displayName = 'GlassMenuLabel';

/** A hairline between groups of menu rows. */
export const GlassMenuSeparator = forwardRef<View, ViewProps>((props, ref) => (
  <OverlaySeparator ref={ref} {...props} />
));

GlassMenuSeparator.displayName = 'GlassMenuSeparator';

/** Groups related menu rows. */
export const GlassMenuGroup = forwardRef<View, ViewProps>((props, ref) => (
  <View ref={ref} {...props} />
));

GlassMenuGroup.displayName = 'GlassMenuGroup';

/** Trailing muted text on a menu row, such as a keyboard shortcut. */
export const GlassMenuShortcut = forwardRef<Text, TextProps>(({ style, ...rest }, ref) => {
  const { colors } = useGlassTheme();

  return (
    <Text ref={ref} style={[styles.shortcut, { color: colors.mutedForeground }, style]} {...rest} />
  );
});

GlassMenuShortcut.displayName = 'GlassMenuShortcut';

// The web's lg-menu-indicator dot and lg-menu-shortcut.
const styles = StyleSheet.create({
  dot: { borderRadius: 3.25, height: 6.5, width: 6.5 },
  shortcut: { fontSize: 12, letterSpacing: 0.72, marginStart: 'auto', paddingStart: 24 },
});

import {
  cloneElement,
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useState,
  type ReactElement,
  type ReactNode,
  type Ref,
} from 'react';
import {
  Animated,
  I18nManager,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
  useWindowDimensions,
  type AccessibilityState,
  type GestureResponderEvent,
  type LayoutChangeEvent,
  type PressableProps,
  type StyleProp,
  type TextProps,
  type TextStyle,
  type ViewProps,
  type ViewStyle,
} from 'react-native';
import { initialWindowMetrics, SafeAreaInsetsContext } from 'react-native-safe-area-context';
import { useGlassTheme } from '../glass-provider';
import { GlassSurface } from '../glass-surface';
import { LAYER_EASING, ModalLayerHost, useLayerPresence } from './modal-layer';
import { wrapPlainText } from './plain-text';
import { GLASS_MOTION } from './tokens';

export type OverlaySide = 'top' | 'bottom';

export type OverlayAlign = 'start' | 'center' | 'end';

export type OverlayPlacementProps = {
  /** The trigger edge the layer lines up with. Start and end follow the reading direction. */
  align?: OverlayAlign;
  /** The side of the trigger the layer opens on. It flips when the other side has more room. */
  side?: OverlaySide;
  /** The gap between the trigger and the layer, in points. Defaults to 6. */
  sideOffset?: number;
};

type Rect = { height: number; width: number; x: number; y: number };

type Size = { height: number; width: number };

type Bounds = { bottom: number; left: number; right: number; top: number };

type Placement = {
  /** The tallest the layer may be on its side; beyond that it scrolls. */
  maxHeight: number;
  /** Where the trigger's centre falls across the layer, the point it grows from. */
  originX: number;
  side: OverlaySide;
  /** The layer's left edge and top edge in window coordinates. */
  x: number;
  y: number;
};

// Layers keep this far inside the window and its safe areas.
const EDGE_MARGIN = 8;

const DEFAULT_SIDE_OFFSET = 6;

// A layer grows out of its trigger from 94% and drifts its last few points away from it.
const ENTER_SCALE = 0.94;

const DRIFT = 4;

// The web's lg-pop-in and lg-pop-out: arrivals ease out, exits ease in and run shorter.
const ENTER = { duration: 240, easing: LAYER_EASING.out };

const EXIT = { duration: 160, easing: LAYER_EASING.in };

const MIRRORED_ALIGN = { center: 'center', end: 'start', start: 'end' } as const satisfies Record<
  OverlayAlign,
  OverlayAlign
>;

const NO_INSETS = { bottom: 0, left: 0, right: 0, top: 0 };

function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), Math.max(min, max));
}

/** Where a layer of `size` sits beside `anchor`, kept inside `bounds`. All in window points. */
function placeLayer(
  anchor: Rect,
  size: Size,
  bounds: Bounds,
  preferred: OverlaySide,
  align: OverlayAlign,
  sideOffset: number,
): Placement {
  const below = anchor.y + anchor.height + sideOffset;
  const above = anchor.y - sideOffset;
  const room = { bottom: bounds.bottom - below, top: above - bounds.top };
  const other = preferred === 'bottom' ? 'top' : 'bottom';
  const side = size.height > room[preferred] && room[other] > room[preferred] ? other : preferred;
  const maxHeight = Math.max(room[side], 0);
  const height = Math.min(size.height, maxHeight);
  const y = clamp(side === 'bottom' ? below : above - height, bounds.top, bounds.bottom - height);
  const edge = I18nManager.isRTL ? MIRRORED_ALIGN[align] : align;

  const offset = {
    center: (anchor.width - size.width) / 2,
    end: anchor.width - size.width,
    start: 0,
  };

  const x = clamp(anchor.x + offset[edge], bounds.left, bounds.right - size.width);

  return {
    maxHeight,
    originX: clamp(anchor.x + anchor.width / 2 - x, 0, size.width),
    side,
    x,
    y,
  };
}

/**
 * Puts a placed layer in position and grows it out of its trigger as `progress` runs from 0 to 1.
 * Yoga reads start and end by reading direction, so in right-to-left layouts end is the left edge.
 */
function layerMotion(placement: Placement, progress: Animated.Value) {
  const drift = placement.side === 'top' ? DRIFT : -DRIFT;
  const originY = placement.side === 'top' ? '100%' : '0px';

  return [
    I18nManager.isRTL ? { end: placement.x } : { start: placement.x },
    {
      top: placement.y,
      transform: [
        { translateY: progress.interpolate({ inputRange: [0, 1], outputRange: [drift, 0] }) },
        { scale: progress.interpolate({ inputRange: [0, 1], outputRange: [ENTER_SCALE, 1] }) },
      ],
      // React Native reads whole points here, so the origin is rounded.
      transformOrigin: `${Math.round(placement.originX)}px ${originY}`,
    },
  ];
}

/** Points `ref` at `node`, whether it is a callback or an object ref. */
export function assignRef<T>(ref: Ref<T> | undefined, node: T | null) {
  if (ref instanceof Function) {
    ref(node);

    return;
  }

  if (ref) ref.current = node;
}

export type OverlayTriggerChildProps = {
  accessibilityState?: AccessibilityState;
  onPress?: ((event: GestureResponderEvent) => void) | null;
  ref?: Ref<View>;
};

type OverlayTriggerProps = {
  children: ReactElement<OverlayTriggerChildProps>;
  /** Receives the child's view, which the layer measures to know where to open. */
  onAnchor: (node: View | null) => void;
  onOpenChange: (open: boolean) => void;
  open: boolean;
};

/**
 * Renders its one child with a press that toggles the layer and an expanded state. The child's
 * own press and ref keep working; the child must pass its ref to a view, which the layer measures.
 */
export function OverlayTrigger({ children, onAnchor, onOpenChange, open }: OverlayTriggerProps) {
  const { accessibilityState, onPress, ref: forwarded } = children.props;

  const ref = useCallback(
    (node: View | null) => {
      onAnchor(node);
      assignRef(forwarded, node);
    },
    [forwarded, onAnchor],
  );

  const handlePress = useCallback(
    (event: GestureResponderEvent) => {
      onPress?.(event);

      if (!event.isDefaultPrevented()) onOpenChange(!open);
    },
    [onOpenChange, onPress, open],
  );

  return cloneElement(children, {
    accessibilityState: { ...accessibilityState, expanded: open },
    onPress: handlePress,
    ref,
  });
}

export type AnchoredContentProps = Omit<ViewProps, 'children' | 'style'> &
  OverlayPlacementProps & {
    /** The view the layer opens beside, usually its trigger. */
    anchor: View | null;
    children?: ReactNode;
    /** Keeps the children mounted in a hidden, inert view while the layer is closed. */
    keepMounted?: boolean;
    /** The layer's narrowest width in points, or 'trigger' for at least the trigger's width. */
    minWidth?: number | 'trigger';
    onClose: () => void;
    open: boolean;
    /** Space between the glass edge and the content that scrolls inside it. */
    padding: number;
    radius: number;
    /** Applies to the glass. */
    style?: StyleProp<ViewStyle>;
  };

type AnchoredLayerProps = Omit<AnchoredContentProps, 'keepMounted'> & {
  onExited: () => void;
};

const AnchoredLayer = forwardRef<View, AnchoredLayerProps>(
  (
    {
      align = 'center',
      anchor,
      children,
      minWidth = 0,
      onClose,
      onExited,
      open,
      padding,
      radius,
      side = 'bottom',
      sideOffset = DEFAULT_SIDE_OFFSET,
      style,
      ...rest
    },
    ref,
  ) => {
    const { preferences } = useGlassTheme();
    const viewport = useWindowDimensions();
    const insets = useContext(SafeAreaInsetsContext) ?? initialWindowMetrics?.insets ?? NO_INSETS;
    const [progress] = useState(() => new Animated.Value(0));
    const [frame, setFrame] = useState<Rect | null>(null);
    const [size, setSize] = useState<Size | null>(null);

    const bounds = {
      bottom: viewport.height - insets.bottom - EDGE_MARGIN,
      left: insets.left + EDGE_MARGIN,
      right: viewport.width - insets.right - EDGE_MARGIN,
      top: insets.top + EDGE_MARGIN,
    };

    const widest = bounds.right - bounds.left;
    const narrowest = Math.min(minWidth === 'trigger' ? (frame?.width ?? 0) : minWidth, widest);

    // Find the trigger when the layer opens, and again when the window turns or resizes.
    useLayoutEffect(() => {
      anchor?.measureInWindow((x, y, width, height) => setFrame({ height, width, x, y }));
    }, [anchor, viewport.height, viewport.width]);

    // A layer that opens with its trigger gets the trigger's view a render later, so only an
    // anchor still missing on the next frame is a mistake.
    useEffect(() => {
      if (anchor) return;

      const frameId = requestAnimationFrame(() =>
        console.error(
          'Glassy UI: a menu, select or popover opened without a trigger to anchor to. Its trigger child must pass its ref to a view.',
        ),
      );

      return () => cancelAnimationFrame(frameId);
    }, [anchor]);

    const handleLayout = useCallback((event: LayoutChangeEvent) => {
      const { height, width } = event.nativeEvent.layout;

      setSize((previous) =>
        previous?.height === height && previous.width === width ? previous : { height, width },
      );
    }, []);

    // A size measured before the trigger's width applied is stale; the next layout replaces it.
    const placement =
      frame && size && size.width >= narrowest - 0.5
        ? placeLayer(frame, size, bounds, side, align, sideOffset)
        : null;

    const placed = placement !== null;

    useEffect(() => {
      if (!placed) {
        if (!open) onExited();

        return;
      }

      if (preferences.reduceMotion) {
        progress.setValue(open ? 1 : 0);

        if (!open) onExited();

        return;
      }

      const motion = open ? ENTER : EXIT;

      const animation = Animated.timing(progress, {
        duration: motion.duration,
        easing: motion.easing,
        toValue: open ? 1 : 0,
        useNativeDriver: GLASS_MOTION.nativeDriver,
      });

      animation.start(({ finished }) => {
        if (finished && !open) onExited();
      });

      return () => animation.stop();
    }, [onExited, open, placed, preferences.reduceMotion, progress]);

    return (
      <>
        <Pressable
          accessible={false}
          importantForAccessibility="no"
          onPress={onClose}
          style={StyleSheet.absoluteFill}
        />
        <Animated.View
          onLayout={handleLayout}
          pointerEvents={placed ? 'auto' : 'none'}
          style={[styles.layer, placement ? layerMotion(placement, progress) : styles.measuring]}
        >
          <GlassSurface
            ref={ref}
            elevation="raised"
            preset="overlay"
            style={[
              {
                borderRadius: radius,
                maxHeight: placement?.maxHeight ?? bounds.bottom - bounds.top,
                maxWidth: widest,
                minWidth: narrowest,
              },
              style,
            ]}
            {...rest}
            accessibilityViewIsModal
            onAccessibilityEscape={onClose}
          >
            <ScrollView
              alwaysBounceVertical={false}
              contentContainerStyle={{ padding }}
              keyboardShouldPersistTaps="handled"
              style={{
                borderCurve: 'continuous',
                borderRadius: StyleSheet.flatten(style)?.borderRadius ?? radius,
              }}
            >
              {children}
            </ScrollView>
          </GlassSurface>
        </Animated.View>
      </>
    );
  },
);

AnchoredLayer.displayName = 'AnchoredLayer';

/**
 * A glass layer anchored to a trigger. It opens in a transparent modal, measures itself before it
 * shows, grows out of the trigger and closes on an outside tap or the Android back button. Glass
 * never fades: it scales and drifts, and Reduce Motion shows and hides it at once.
 */
export const AnchoredContent = forwardRef<View, AnchoredContentProps>(
  ({ children, keepMounted = false, onClose, open, ...rest }, ref) => {
    const { preferences } = useGlassTheme();
    const [present, hide] = useLayerPresence(open, preferences.reduceMotion);

    return (
      <>
        <ModalLayerHost onRequestClose={onClose} present={present}>
          <AnchoredLayer ref={ref} onClose={onClose} onExited={hide} open={open} {...rest}>
            {children}
          </AnchoredLayer>
        </ModalLayerHost>
        {keepMounted && !present ? (
          <View
            accessibilityElementsHidden
            importantForAccessibility="no-hide-descendants"
            style={[{ pointerEvents: 'none' }, styles.hidden]}
          >
            {children}
          </View>
        ) : null}
      </>
    );
  },
);

AnchoredContent.displayName = 'AnchoredContent';

export type OverlayItemProps = Omit<PressableProps, 'children' | 'style'> & {
  children?: ReactNode;
  /** A check or dot drawn in the inset at the row's start. */
  indicator?: ReactNode;
  /** Leaves room for an indicator at the start, so labels line up. */
  inset?: boolean;
  style?: StyleProp<ViewStyle>;
  textStyle?: StyleProp<TextStyle>;
  tone?: 'default' | 'destructive';
};

// A pressed row lightens dark glass and darkens light glass, as .lg-menu-item[data-highlighted].
const PRESSED_ROW = { dark: 'rgba(255, 255, 255, 0.14)', light: 'rgba(0, 0, 0, 0.06)' } as const;

/** A 44-point row in a menu or a select list; a press tints the row under it. */
export const OverlayItem = forwardRef<View, OverlayItemProps>(
  (
    {
      children,
      disabled = false,
      indicator,
      inset = false,
      style,
      textStyle,
      tone = 'default',
      ...rest
    },
    ref,
  ) => {
    const { colors, preferences } = useGlassTheme();
    const ink = tone === 'destructive' ? colors.invalid : colors.foreground;

    return (
      <Pressable
        ref={ref}
        accessibilityRole="menuitem"
        disabled={disabled}
        style={({ pressed }) => [
          styles.item,
          inset && styles.inset,
          pressed && { backgroundColor: PRESSED_ROW[preferences.theme] },
          disabled && styles.disabled,
          style,
        ]}
        {...rest}
      >
        {indicator ? <View style={styles.indicator}>{indicator}</View> : null}
        {wrapPlainText(children, (text) => (
          <Text style={[styles.itemText, { color: ink }, textStyle]}>{text}</Text>
        ))}
      </Pressable>
    );
  },
);

OverlayItem.displayName = 'OverlayItem';

/** A small muted heading over a group of rows. */
export const OverlayLabel = forwardRef<Text, TextProps>(({ style, ...rest }, ref) => {
  const { colors } = useGlassTheme();

  return (
    <Text
      ref={ref}
      accessibilityRole="header"
      style={[styles.label, { color: colors.mutedForeground }, style]}
      {...rest}
    />
  );
});

OverlayLabel.displayName = 'OverlayLabel';

/** A hairline between groups of rows. Screen readers skip it. */
export const OverlaySeparator = forwardRef<View, ViewProps>(({ style, ...rest }, ref) => {
  const { colors } = useGlassTheme();

  return (
    <View
      ref={ref}
      accessibilityElementsHidden
      importantForAccessibility="no"
      style={[styles.separator, { backgroundColor: colors.border }, style]}
      {...rest}
    />
  );
});

OverlaySeparator.displayName = 'OverlaySeparator';

// Rows, labels and separators copy the web's lg-menu-item, lg-menu-label and lg-menu-separator.
// Rows grow from the web's 36 pixels to a 44-point touch target.
const styles = StyleSheet.create({
  disabled: { opacity: 0.45 },
  hidden: { display: 'none' },
  indicator: {
    alignItems: 'center',
    bottom: 0,
    justifyContent: 'center',
    position: 'absolute',
    start: 8,
    top: 0,
    width: 16,
  },
  inset: { paddingStart: 32 },
  item: {
    alignItems: 'center',
    borderCurve: 'continuous',
    borderRadius: 12,
    flexDirection: 'row',
    gap: 10,
    minHeight: 44,
    paddingHorizontal: 12,
    paddingVertical: 7,
  },
  itemText: { flexShrink: 1, fontSize: 14, lineHeight: 20 },
  label: {
    fontSize: 12,
    fontWeight: '600',
    lineHeight: 16,
    paddingBottom: 4,
    paddingHorizontal: 12,
    paddingTop: 6,
  },
  layer: { position: 'absolute' },
  // Until it is measured, a layer waits off screen so it never shows in the wrong place.
  measuring: { start: 0, top: -10000 },
  separator: { height: 1, marginHorizontal: 10, marginVertical: 6 },
});

import { View } from 'react-native';
import Svg, { Path } from 'react-native-svg';

export type GlassIconName =
  | 'check'
  | 'chevron-down'
  | 'chevron-right'
  | 'close'
  | 'dash'
  | 'danger'
  | 'info'
  | 'success'
  | 'warning';

// The web components' own strokes, drawn on a 20-point grid.
const PATHS = {
  check: ['M4.5 10.5 8.25 14.25 15.5 6.25'],
  'chevron-down': ['M5 7.5l5 5 5-5'],
  'chevron-right': ['M7.5 4.4 13.1 10l-5.6 5.6'],
  close: ['M5.5 5.5l9 9m0-9l-9 9'],
  dash: ['M5 10h10'],
  danger: ['M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Z', 'M7.6 7.6l4.8 4.8', 'M12.4 7.6l-4.8 4.8'],
  info: ['M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Z', 'M10 9.2v4.1', 'M10 6.7h.01'],
  success: ['M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Z', 'M6.9 10.2l2.2 2.2 4-4.4'],
  warning: ['M10 3.6 17 16H3L10 3.6Z', 'M10 8.4v3.4', 'M10 14h.01'],
} as const satisfies Record<GlassIconName, readonly string[]>;

export type GlassIconProps = {
  color: string;
  name: GlassIconName;
  size?: number;
  strokeWidth?: number;
};

/** A stroked glyph from the library's small icon set. Decorative; label its control instead. */
export function GlassIcon({ color, name, size = 20, strokeWidth = 1.8 }: GlassIconProps) {
  // The hiding lives on a View: on the web, Svg passes its props to a bare <svg> element.
  return (
    <View
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
      style={{ height: size, width: size }}
    >
      <Svg width={size} height={size} viewBox="0 0 20 20" fill="none">
        {PATHS[name].map((path) => (
          <Path
            key={path}
            d={path}
            stroke={color}
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={strokeWidth}
          />
        ))}
      </Svg>
    </View>
  );
}

import {
  Children,
  cloneElement,
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ReactElement,
  type ReactNode,
} from 'react';
import {
  Animated,
  Easing,
  I18nManager,
  Modal,
  Pressable,
  StyleSheet,
  Text,
  type AccessibilityState,
  type GestureResponderEvent,
  type ModalProps,
  type StyleProp,
  type TextProps,
  type ViewStyle,
} from 'react-native';
import { initialWindowMetrics, SafeAreaInsetsContext } from 'react-native-safe-area-context';
import { useGlassTheme } from '../glass-provider';
import { GlassIcon } from './icons';
import { useControllableState } from './use-controllable-state';

/** Arrivals ease out on the library's curve (`--lg-ease-out`); exits ease in. */
export const LAYER_EASING = {
  in: Easing.bezier(0.42, 0, 1, 1),
  out: Easing.bezier(0.32, 0.72, 0, 1),
};

/** The fill of a control on glass under a finger (`--lg-control-surface-hover`). */
export const CONTROL_SURFACE_PRESSED = {
  dark: 'rgba(245, 245, 247, 0.14)',
  light: 'rgba(255, 255, 255, 0.95)',
} as const;

// Without these, iOS turns a landscape screen back to portrait while a layer is open.
const ORIENTATIONS = [
  'portrait',
  'portrait-upside-down',
  'landscape',
  'landscape-left',
  'landscape-right',
] satisfies ModalProps['supportedOrientations'];

/**
 * The screen's safe-area insets, with start and end following the layout direction. Reads the
 * nearest SafeAreaProvider, or the window's first measurement when there is none.
 */
export function useSafeInsets() {
  const insets = useContext(SafeAreaInsetsContext) ?? initialWindowMetrics?.insets;
  const left = insets?.left ?? 0;
  const right = insets?.right ?? 0;

  return {
    bottom: insets?.bottom ?? 0,
    end: I18nManager.isRTL ? left : right,
    start: I18nManager.isRTL ? right : left,
    top: insets?.top ?? 0,
  };
}

/**
 * Whether a layer is on screen. It turns true with `open` and stays true until the layer calls
 * `hide` at the end of its exit, so the exit can play. Under Reduce Motion it turns false at once.
 */
export function useLayerPresence(open: boolean, reduceMotion: boolean) {
  const [present, setPresent] = useState(open);

  if (open && !present) setPresent(true);

  if (!open && present && reduceMotion) setPresent(false);

  const hide = useCallback(() => setPresent(false), []);

  return [present, hide] as const;
}

type ModalLayerState = {
  open: boolean;
  setOpen: (open: boolean) => void;
};

const ModalLayerContext = createContext<ModalLayerState | null>(null);

export type ModalLayerRootProps = {
  children?: ReactNode;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  open?: boolean;
};

/** Holds a modal layer's open state for its trigger, content and close controls. */
export function ModalLayerRoot({
  children,
  defaultOpen = false,
  onOpenChange,
  open,
}: ModalLayerRootProps) {
  const [current, setOpen] = useControllableState(open, defaultOpen, onOpenChange);
  const value = useMemo(() => ({ open: current, setOpen }), [current, setOpen]);

  return <ModalLayerContext.Provider value={value}>{children}</ModalLayerContext.Provider>;
}

/** The nearest modal layer's state. `component` and `root` name the parts in the error. */
export function useModalLayer(component: string, root: string) {
  const context = useContext(ModalLayerContext);

  if (!context) throw new Error(`${component} must be used within ${root}`);

  return context;
}

type PressableChildProps = {
  accessibilityState?: AccessibilityState;
  onPress?: ((event: GestureResponderEvent) => void) | null;
};

export type ModalLayerSlotProps = {
  /** One pressable element, such as a GlassButton. It keeps its own onPress. */
  children: ReactElement<PressableChildProps>;
};

type SlotOwnerProps = ModalLayerSlotProps & {
  component: string;
  root: string;
};

/** Gives its child an onPress that toggles the layer, and tells assistive tech whether it is open. */
export function ModalLayerTrigger({ children, component, root }: SlotOwnerProps) {
  const { open, setOpen } = useModalLayer(component, root);
  const child = Children.only(children);

  return cloneElement(child, {
    accessibilityState: { ...child.props.accessibilityState, expanded: open },
    onPress: (event: GestureResponderEvent) => {
      child.props.onPress?.(event);
      setOpen(!open);
    },
  });
}

/** Gives its child an onPress that closes the layer. */
export function ModalLayerClose({ children, component, root }: SlotOwnerProps) {
  const { setOpen } = useModalLayer(component, root);
  const child = Children.only(children);

  return cloneElement(child, {
    onPress: (event: GestureResponderEvent) => {
      child.props.onPress?.(event);
      setOpen(false);
    },
  });
}

type ModalLayerHostProps = {
  children: ReactNode;
  /** Android's back button and the web's Escape key. */
  onRequestClose: () => void;
  present: boolean;
};

/** React Native's Modal, set up for a layer that draws its own scrim and animates itself. */
export function ModalLayerHost({ children, onRequestClose, present }: ModalLayerHostProps) {
  return (
    <Modal
      animationType="none"
      navigationBarTranslucent
      onRequestClose={onRequestClose}
      statusBarTranslucent
      supportedOrientations={ORIENTATIONS}
      transparent
      visible={present}
    >
      {present ? children : null}
    </Modal>
  );
}

type ModalLayerScrimProps = {
  onPress: () => void;
  /** 0 hidden, 1 shown. */
  progress: Animated.Value;
};

/** The dimmed backdrop behind a modal layer. It fades with `progress`; a tap on it closes the layer. */
export function ModalLayerScrim({ onPress, progress }: ModalLayerScrimProps) {
  const { colors } = useGlassTheme();

  return (
    <>
      <Animated.View
        style={[
          { pointerEvents: 'none' },
          StyleSheet.absoluteFill,
          { backgroundColor: colors.scrim, opacity: progress },
        ]}
      />
      <Pressable
        accessible={false}
        importantForAccessibility="no"
        onPress={onPress}
        style={StyleSheet.absoluteFill}
      />
    </>
  );
}

type ModalLayerCloseButtonProps = {
  label: string;
  onPress: () => void;
  /** Places the button; it is absolutely positioned. */
  style?: StyleProp<ViewStyle>;
};

/** The round close button in a layer's top corner, with a 44-point target. */
export function ModalLayerCloseButton({ label, onPress, style }: ModalLayerCloseButtonProps) {
  const { colors, preferences } = useGlassTheme();

  return (
    <Pressable
      accessibilityLabel={label}
      accessibilityRole="button"
      hitSlop={4}
      onPress={onPress}
      style={({ pressed }) => [
        styles.close,
        {
          backgroundColor: pressed
            ? CONTROL_SURFACE_PRESSED[preferences.theme]
            : colors.controlSurface,
          borderColor: colors.border,
        },
        style,
      ]}
    >
      {({ pressed }) => (
        <GlassIcon
          color={pressed ? colors.foreground : colors.mutedForeground}
          name="close"
          size={16}
          strokeWidth={1.6}
        />
      )}
    </Pressable>
  );
}

/** A layer's heading, announced as a header and kept clear of the close button. */
export const ModalLayerTitle = forwardRef<Text, TextProps>(({ style, ...rest }, ref) => {
  const { colors } = useGlassTheme();

  return (
    <Text
      ref={ref}
      accessibilityRole="header"
      style={[styles.title, { color: colors.foreground }, style]}
      {...rest}
    />
  );
});

ModalLayerTitle.displayName = 'ModalLayerTitle';

/** A layer's supporting text, in the muted ink. */
export const ModalLayerDescription = forwardRef<Text, TextProps>(({ style, ...rest }, ref) => {
  const { colors } = useGlassTheme();

  return (
    <Text
      ref={ref}
      style={[styles.description, { color: colors.mutedForeground }, style]}
      {...rest}
    />
  );
});

ModalLayerDescription.displayName = 'ModalLayerDescription';

const styles = StyleSheet.create({
  close: {
    alignItems: 'center',
    borderCurve: 'continuous',
    borderRadius: 18,
    borderWidth: 1,
    height: 36,
    justifyContent: 'center',
    position: 'absolute',
    width: 36,
  },
  description: { fontSize: 15, lineHeight: 21, marginTop: 6 },
  // The close button sits 16 points in from the corner; the title stops 8 points short of it.
  title: { fontSize: 20, fontWeight: '600', letterSpacing: -0.3, lineHeight: 25, paddingEnd: 36 },
});

import { Children, isValidElement, type ReactNode } from 'react';

/**
 * Sets plain text inside a Text, which React Native needs to render it. Content that is all text
 * becomes one Text; beside elements such as icons, each run of text gets its own.
 */
export function wrapPlainText(node: ReactNode, render: (text: ReactNode) => ReactNode) {
  const parts = Children.toArray(node);

  if (parts.length === 0) return null;

  if (parts.every((part) => !isValidElement(part))) return render(node);

  return Children.map(node, (part) => (isValidElement(part) ? part : render(part)));
}

/** The words in `node` when it is only text, to name a control for assistive technology. */
export function plainTextOf(node: ReactNode) {
  const parts = Children.toArray(node);

  return parts.length > 0 && parts.every((part) => !isValidElement(part))
    ? parts.join('')
    : undefined;
}
